SET SESSION group_concat_max_len = 16777216;
SET @jpa = (SELECT p.id FROM posts p WHERE p.id = 103 AND p.slug = 'jpa' AND p.updated_at = '2026-08-05 14:39:51.572574' AND (SELECT COUNT(*) FROM post_block b WHERE b.post_id = 103) = 213 AND (SELECT MD5(GROUP_CONCAT(CONCAT(b.block_order, CHAR(30), b.block_type, CHAR(30), COALESCE(b.content, '')) ORDER BY b.block_order SEPARATOR 0x1f)) FROM post_block b WHERE b.post_id = 103) = 'a105370e92edbe3160c3e3e3eca9f549');
DELETE FROM post_block WHERE post_id = @jpa AND block_order >= 183;
SET @java8 = (SELECT p.id FROM posts p WHERE p.id = 118 AND p.slug = 'java-8' AND p.updated_at = '2026-09-25 12:54:20.296197' AND (SELECT COUNT(*) FROM post_block b WHERE b.post_id = 118) = 113 AND (SELECT MD5(GROUP_CONCAT(CONCAT(b.block_order, CHAR(30), b.block_type, CHAR(30), COALESCE(b.content, '')) ORDER BY b.block_order SEPARATOR 0x1f)) FROM post_block b WHERE b.post_id = 118) = '8aac2e659f520eb172845bc9a0034638');
DELETE FROM post_block WHERE post_id = @java8 AND block_order >= 73;
