INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'CODE', '{"lang":"java","code":"@Entity\\npublic class Student {\\n\\n    @Id\\n    @NaturalId  // Hibernateでは自然キーとして認識\\n    @Column(name = \\"student_number\\", nullable = false, unique = true)\\n    private Long studentNumber;"}', 183, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'QUOTE', '[!NOTE]\n### 代理キーを使用すべき理由\n\n- ビジネス（ドメイン）は常に変化しうるためです\n- もし自然キーが複雑な場合、インデックス作成などデータベース側の問題に柔軟に対応できなくなります\n\nこのような理由から、代理キーを使用することが望ましいと考えられます。', 184, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '#### 単純キー (Simple Key) と複合キー (Compound Key)', 185, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'LIST_BULLET', '- **単純キー (Simple Key)**: 識別子が1つの場合', 186, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'CODE', '{"lang":"java","code":"@Entity\\npublic class Student {\\n\\n    @Id\\n    @GeneratedValue(strategy = GenerationType.IDENTITY) \\n    private Long id;"}', 187, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'LIST_BULLET', '- **複合キー (Compound Key)**: 識別子が複数の場合', 188, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'CODE', '{"lang":"java","code":"@Entity\\n@IdClass(StudentId.class)\\npublic class Student {\\n\\n    @Id\\n    private String department;    // 例: 学科コード\\n\\n    @Id\\n    private String studentNumber;   // 例: 学籍番号"}', 189, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'QUOTE', '[!NOTE]\n### 単純キーを複合キーより好む理由\n\n- ビジネス（ドメイン）は常に変更される可能性があります\n- エンティティ間の関係設定の観点でも、単純キーの方が一貫性があり、直感的に管理できます\n\nこのような理由から、単純キーを好むと考えられます。', 190, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '#### 生成キー (Generated Key) vs 割り当てキー (Assigned Key)', 191, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'LIST_BULLET', '- **生成キー (Generated Key)**: JPAまたはDBが生成するキー\n\n  ```java\n  @Entity\n  public class Student {\n  \n      // データベースが自動的に生成するキー（例：auto-increment）\n      @Id\n      @GeneratedValue(strategy = GenerationType.IDENTITY)\n      private Long id;\n  }\n  ```\n- **割り当てキー (Assigned Key)**: アプリケーションまたはドメインロジックにより直接割り当てられるキー', 192, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'CODE', '{"lang":"java","code":"@Entity\\npublic class Student {\\n    // アプリケーションで直接割り当てるキー（例: 学籍番号）\\n    @Id\\n    @NaturalId // Hibernateでは自然キーとしても使用\\n    @Column(name = \\"student_number\\", nullable = false, unique = true)\\n    private Long studentNumber;"}', 193, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'QUOTE', '[!NOTE]\n### 生成キーを好む理由\n\n- 管理や安定性の観点から、生成キー方式は直感的です\n- ビジネス（ドメイン）は常に変更される可能性があるためです\n\nこのような理由から、生成キー方式が優れていると考えられます。', 194, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'H3', 'find(); を使用して 1次キャッシュとDBからデータを取得する', 195, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/91fc7dca-56cc-4816-8de7-56733aeee19b.png","alt":"image.png"}', 196, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '`find();` を使用して、DBからデータを取得し、1次キャッシュに保持する方法があります。', 197, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '動作は次の通りです。', 198, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'LIST_NUMBERED', '1. 1次キャッシュ（Identity Map）に対象のオブジェクトが存在するかを確認します\n\n   ![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/9328b4f1-bc7d-4c2d-9c88-89575ecf0b46.png)\n\n   存在すれば、そのオブジェクトを返却します。', 199, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'QUOTE', '[!NOTE]\n1次キャッシュのこの動作により、作業範囲（トランザクション）内では識別子の同一性に応じて同一のオブジェクトが返却されることが保証されます。\\\nまた、1次キャッシュにオブジェクトが既に存在する場合、SELECTクエリは発生しません。', 200, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'LIST_NUMBERED', '2. もし存在しなければ、データベースに対してSELECTクエリを発行し、データを取得してJavaオブジェクトにマッピングした後、永続性コンテキストに登録し、返却します。\n\n   ![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/70772c1d-0357-4d2b-be24-894721c290f6.png)\n\n   ![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/8512b24b-25d4-4ce1-aa95-be78c0cabbd1.png)\n\n   ![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/a8feea77-40bf-492f-bd5c-092c29d2b6b1.png)', 201, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', 'もしDBにも存在しなければ、nullが返されます。', 202, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'H2', 'Removed 状態', 203, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/4075a530-67ed-4845-bf0c-17d8d8d23f5f.png","alt":"image.png"}', 204, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '`remove();` メソッドを通じ、永続状態のエンティティを削除対象としてマークすることができます。', 205, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'LIST_BULLET', '- 次に `flush();` を呼び出すと、データベースに対して DELETE クエリが発行され、実際に削除されます\n- `remove();` は永続状態にあるエンティティを削除対象に変更するだけであり、依然として永続性コンテキストで管理されるオブジェクトです。\n- つまり、永続状態でないオブジェクトには `remove();` を使用することはできません', 206, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'QUOTE', '[!NOTE]\nつまり、JPAで削除を実行するためには、必ず識別子（@Id）を用いてエンティティを永続状態に登録する必要があるため、ほとんどの場合 `find();` を通じたSELECTクエリが発生します。', 207, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/d08e21e6-c86e-45b4-ab99-2c91081d9628.png","alt":"image.png"}', 208, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/d0ba874b-aea2-44f3-bb77-e1136d90119e.png","alt":"image.png"}', 209, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '\\\n`package org.hibernate.event.internal.EntityStatus` を確認すると、動作構造を詳しく把握することができます。', 210, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '以下は、永続状態のエンティティを削除する際の動作を示しています。', 211, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/7f904cb1-106e-4285-9510-ddeeab212375.png","alt":"image.png"}', 212, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '次のようなテストコードがあります。', 213, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'CODE', '{"lang":"java","code":"Student findStudent = entityManager.find(Student.class, 1L);\\nentityManager.remove(findStudent);"}', 214, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', 'これにより、エンティティが Removed 状態に変更されます。\\\nその後、以下のように Removed 状態に設定されたエンティティを取得しようとすると、', 215, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'CODE', '{"lang":"java","code":"Student removedStudent = entityManager.find(Student.class, student.getId());\\nassertNull(removedStudent);"}', 216, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '永続性コンテキスト（1次キャッシュ）からも値は見つかりません。', 217, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/0f432236-211f-424e-9a9d-0bb57ed6e812.png","alt":"image.png"}', 218, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', 'しかしながら、これはあくまで永続性コンテキスト上で管理されているオブジェクトであり、flush() を呼び出さない限り、データベース上からは削除されません。\\\n該当テストコードのログを確認すると、以下のように DELETE クエリは発生していません。', 219, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/6725d7ac-f907-4743-9903-143bf7d77d33.png","alt":"image.png"}', 220, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'H3', 'Removed 状態のオブジェクトを再び永続化する', 221, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '通常、Removed 状態になったオブジェクトを再び永続状態に戻すことはほとんどありませんが、理解を深めるために、以下のような状況を考えてみましょう。', 222, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', 'ポイントは、永続性コンテキスト（Identity Map）に登録されているか否かです。\\\n次のようなコードは、', 223, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/545f6f81-afcc-453e-844f-404b72f5bcec.png","alt":"image.png"}', 224, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'CODE', '{"lang":"java","code":"entityManager.remove(student);"}', 225, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '状態遷移: **Managed → Removed**\\\n`remove()` を呼び出すと、エンティティの状態は Removed に変更され、削除対象としてマークされます。\\\n（ただし、まだ `flush()` を呼び出していないため、データベース上では実際には削除されていません。）', 226, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'CODE', '{"lang":"java","code":"entityManager.detach(student);"}', 227, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '状態遷移: **Removed → Detached**\\\n`detach()` を呼び出すと、永続性コンテキストから該当エンティティが分離され、Detached 状態になります。\\\nこの時点で、削除予約（Removed 状態）はキャンセルされます。', 228, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'CODE', '{"lang":"java","code":"Student reattachedStudent = entityManager.merge(student);"}', 229, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '状態遷移: **Detached → Managed**\\\n`merge()` を呼び出すと、Detached 状態のエンティティが再び永続性コンテキストにマージされ、新たな Managed インスタンス（reattachedStudent）が返されます。\\\nこの際、同一の識別子（ID）の値が保持されます。', 230, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'H2', 'Destached', 231, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/cc276dd4-462e-49a7-9ca4-088352b3409e.png","alt":"image.png"}', 232, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '以前のテストコードで使用したように、', 233, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'CODE', '{"lang":"java","code":"entityManager.detach(student);"}', 234, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', 'というメソッドを使用しますが、これは永続性コンテキストにおいて該当オブジェクトの管理を中止することを意味いたします。', 235, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', 'つまり、Identity Map（1次キャッシュ）からそのオブジェクトが除外されます。', 236, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/fb20196f-48b6-4b5b-9429-8ded3e57a783.png","alt":"image.png"}', 237, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '\\\nこの後、以下のようなリクエストが発生すると、', 238, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/0d330cbb-a56a-4497-99d6-07e48fd947f0.png","alt":"image.png"}', 239, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '永続性コンテキスト内から対象オブジェクトが除外された状態となります。', 240, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'CODE', '{"lang":"java","code":"entityManager.clear();"}', 241, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '다음과 같은 메서드를 쓴다면 영속성 컨텍스트에서 관리되는 모든 객체를 영속성 컨텍스트에서 제거한다.', 242, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '次のようなメソッドを使用すると、永続性コンテキストで管理されているすべてのオブジェクトが永続性コンテキストから除外されます。', 243, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'QUOTE', '[!NOTE]\n**非永続状態 (Transient) と 準永続状態 (Detached) の違い**\\\n最も大きな違いは、準永続状態では識別子 (id) が存在するため、再登録時に INSERT クエリが発生しないという点です。', 244, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'H2', 'flush() メソッド', 245, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/21e2bbc5-56bc-4478-a1ef-eead54184ba5.png","alt":"image.png"}', 246, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'LIST_BULLET', '- 永続性コンテキストには、元の状態のスナップショットと該当エンティティが保存されています\n- `flush()` を呼び出すと、メモリ上の変更点を比較し、実際のデータベースに反映するためのクエリが実行されます', 247, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @jpa, 'PARAGRAPH', '簡単に言えば、これまでの変更内容をデータベースと同期させる作業であると言えます。', 248, NOW(6), NOW(6) FROM DUAL WHERE @jpa IS NOT NULL;
