INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @java8, 'CODE', '{"lang":"java","code":"// Bad: 副作用があるコード\\nint sum = 0;\\nlist.forEach(num -> {\\n    sum += num;  // 外部変数を変更（副作用）\\n});\\n\\n// Good: 副作用のないコード\\nint sum = list.stream()\\n             .reduce(0, (a, b) -> a + b);  // 外部変数の変更なし"}', 73, NOW(6), NOW(6) FROM DUAL WHERE @java8 IS NOT NULL;
