INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @java8, 'TABLE', '| 優先順位 | 演算子の種類 | 演算子 | 方向 |\n| --- | --- | --- | --- |\n| 1 | 後置演算子 | expr++, expr-- | →（左から右） |\n| 2 | 単項演算子 | ++expr, --expr, +expr, -expr, \\~, ! | →（左から右） |\n| 3 | 乗算/除算演算子 | \\*, /, % | →（左から右） |\n| 4 | 加算/減算演算子 | +, - | →（左から右） |\n| 5 | シフト演算子 | <<, >>, >>> | →（左から右） |\n| 6 | 関係演算子 | <, >, <=, >=, instanceof | →（左から右） |\n| 7 | 等価演算子 | ==, != | →（左から右） |\n| 8 | ビット論理積 | & | →（左から右） |\n| 9 | ビット排他的論理和 | ^ | →（左から右） |\n| 10 | ビット論理和 | \\| | →（左から右） |\n| 11 | 論理 AND | && | →（左から右） |\n| 12 | 論理 OR | \\|\\| | →（左から右） |\n| 13 | 三項演算子 | ? : | →（左から右） |\n| 14 | 代入演算子 | =, +=, -=, \\*=, /=, %=, &=, ^=, \\|= | ←（右から左） |', 101, NOW(6), NOW(6) FROM DUAL WHERE @java8 IS NOT NULL;
