INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @java8, 'PARAGRAPH', '従来のswitch文には以下の問題が発生します。', 104, NOW(6), NOW(6) FROM DUAL WHERE @java8 IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @java8, 'LIST_NUMBERED', '1. break文を省略すると`フォールスルー（fall-through）`が発生する\n2. 値を返すことができない\n3. 開発者がすべてのケースをチェックしたかをコンパイル時に確認できない', 105, NOW(6), NOW(6) FROM DUAL WHERE @java8 IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @java8, 'CODE', '{"lang":"java","code":"public class SwitchDemo {\\n    public static void main(String[] args) {\\n\\n        int month = 8;\\n        String monthString; // 外部に値を宣言\\n        switch (month) {\\n            // caseを省略する危険がある\\n            case 1:  monthString = \\"January\\";\\n                     break;\\n            case 2:  monthString = \\"February\\";\\n                     break;\\n            case 3:  monthString = \\"March\\";\\n                     break;\\n            case 4:  monthString = \\"April\\";\\n                     break;    // breakを省略するとfall-through問題発生\\n                     // 以下すべての月が出力される\\n            case 5:  monthString = \\"May\\";\\n                     break;\\n            case 6:  monthString = \\"June\\";\\n                     break;\\n            case 7:  monthString = \\"July\\";\\n                     break;\\n            case 8:  monthString = \\"August\\";\\n                     break;\\n            case 9:  monthString = \\"September\\";\\n                     break;\\n            case 10: monthString = \\"October\\";\\n                     break;\\n            case 11: monthString = \\"November\\";\\n                     break;\\n            case 12: monthString = \\"December\\";\\n                     break;\\n            default: monthString = \\"Invalid month\\";\\n                     break;\\n        }\\n        System.out.println(monthString);\\n    }\\n}"}', 106, NOW(6), NOW(6) FROM DUAL WHERE @java8 IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @java8, 'PARAGRAPH', 'このように、switchでは`->`演算子を使用でき、その利点は以下の通りです。', 107, NOW(6), NOW(6) FROM DUAL WHERE @java8 IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @java8, 'LIST_NUMBERED', '1. より簡潔な構文を提供\n2. break文が不要\n3. fall-throughの危険がない（2番と関連し、returnがなくても自動で終了）\n4. 値を返すことが可能\n5. コンパイラがすべてのcaseが処理されているかを検査（完全性チェック）\n6. `yield`を使用してswitchの結果を返すこともできます', 108, NOW(6), NOW(6) FROM DUAL WHERE @java8 IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @java8, 'CODE', '{"lang":"java","code":"public class SwitchDemo {\\n    public static void main(String[] args) {\\n        int month = 8;\\n        \\n        // 基本的なアロー演算子の使用\\n        // 値を直接割り当て\\n        // すべてのcaseが処理されていないとコンパイルエラーが発生\\n        // break文が不要でfall-throughの危険がない\\n        String monthString = switch (month) {\\n            case 1 -> \\"January\\";\\n            case 2 -> \\"February\\";\\n            case 3 -> \\"March\\";\\n            case 4 -> \\"April\\";\\n            case 5 -> \\"May\\";\\n            case 6 -> \\"June\\";\\n            case 7 -> \\"July\\";\\n            case 8 -> \\"August\\";\\n            case 9 -> \\"September\\";\\n            case 10 -> \\"October\\";\\n            case 11 -> \\"November\\";\\n            case 12 -> \\"December\\";\\n            default -> \\"Invalid month\\";\\n        };\\n\\n        // 方法2: 複数のcaseをまとめて処理\\n        String season = switch (month) {\\n            case 12, 1, 2 -> \\"Winter\\";\\n            case 3, 4, 5 -> \\"Spring\\";\\n            case 6, 7, 8 -> \\"Summer\\";\\n            case 9, 10, 11 -> \\"Fall\\";\\n            default -> \\"Invalid month\\";\\n        };\\n\\n        System.out.println(monthString);\\n        System.out.println(season);\\n    }\\n}"}', 109, NOW(6), NOW(6) FROM DUAL WHERE @java8 IS NOT NULL;
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT @java8, 'CODE', '{"lang":"java","code":"// 従来の方法: 外部変数が必要\\nString result;  // 外部変数の宣言が必要\\nswitch(value) {\\n    case 1:\\n        doSomething();\\n        result = \\"ONE\\";  // 外部変数に代入\\n        break;\\n}\\n\\n// 新しい方法: 直接返す\\nString result = switch(value) {  // 直接代入が可能\\n    case 1 -> {\\n        doSomething();\\n        yield \\"ONE\\";    // 直接返却\\n    }\\n};"}', 110, NOW(6), NOW(6) FROM DUAL WHERE @java8 IS NOT NULL;
